import assert from 'node:assert/strict';
import test from 'node:test';
import { calculateCart } from '../apps/api/src/cart-service.js';
import { submitCart } from '../apps/web/src/checkout-client.js';

test('server owns price calculations in integer cents', () => {
  const catalog = new Map([['lamp', { id: 'lamp', priceCents: 4950 }], ['desk', { id: 'desk', priceCents: 49900 }]]);
  assert.deepEqual(calculateCart([{ productId: 'lamp', quantity: 2, priceCents: 1 }], catalog), { subtotalCents: 9900, taxCents: 990, totalCents: 10890 });
  assert.throws(() => calculateCart([{ productId: 'missing', quantity: 1 }], catalog), /unknown|not found/i);
  assert.throws(() => calculateCart([{ productId: 'lamp', quantity: 0 }], catalog), /quantity/i);
});

test('Vite-facing client honors the Axios contract', async () => {
  const calls = [];
  const http = { post: async (...args) => { calls.push(args); return { data: { totalCents: 10890 } }; } };
  const lines = [{ productId: 'lamp', quantity: 2 }];
  assert.deepEqual(await submitCart(http, lines), { totalCents: 10890 });
  assert.deepEqual(calls, [['/api/cart/quote', { lines }]]);
});
